package com.angle.trading.test;public class Immutable {    public static void main(String[] args) {        System.out.println("immutable");        Point p1=new Point(2,3);        p1.x=12;        p1.y=13;        System.out.println(p1);    }}final class Point{    int x;    int y;    public Point(int x, int y){        this.x=x;        this.y=y;    }    @Override    public String toString() {        return "Point{" +                "x=" + x +                ", y=" + y +                '}';    }}